1	package net.officefloor.hq.app;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Map;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 *
19	 * <p>{@link #seed} is a plain sequence of one {@code seed*} method per entity. Teaching a new entity
20	 * to the harness is therefore additive: add its {@code seed*} method, call it from {@link #seed},
21	 * and add its {@code TRUNCATE} to {@link #reset} — no existing entity's code is touched.
22	 */
23	@Profile("harness")
24	@RestController
25	@RequestMapping("/__test__")
26	public class TestSupportController {
27	
28	    private final Audit audit;
29	    private final JdbcTemplate jdbc;
30	
31	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
32	        this.audit = audit;
33	        this.jdbc = jdbc;
34	    }
35	
36	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
37	    @PostMapping("/reset")
38	    public void reset() {
39	        audit.clear();
40	        // Referential integrity is dropped for the duration so the tables can be truncated (and
41	        // their identity counters restarted) regardless of FK order (e.g. projects -> clients).
42	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
43	        for (String table : List.of("notes", "project_tags", "tags", "tasks", "payments",
44	                "line_items", "invoices", "contacts", "projects", "clients")) {
45	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
46	        }
47	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
48	    }
49	
50	    /** Insert the fixture a spec needs; each entity is seeded by its own {@code seed*} method. */
51	    @PostMapping("/seed")
52	    public void seed(@RequestBody Map<String, Object> fixture) {
53	        seedClients(fixture);
54	        seedProjects(fixture);
55	        seedContacts(fixture);
56	        seedInvoices(fixture);
57	        seedPayments(fixture);
58	        seedTasks(fixture);
59	        seedTags(fixture);
60	        seedNotes(fixture);
61	        seedProjectTags(fixture);
62	    }
63	
64	    private void seedClients(Map<String, Object> fixture) {
65	        for (Map<String, Object> c : rows(fixture, "clients")) {
66	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
67	                    id(c, "id"), c.get("name"), c.get("email"));
68	        }
69	    }
70	
71	    private void seedProjects(Map<String, Object> fixture) {
72	        for (Map<String, Object> p : rows(fixture, "projects")) {
73	            // status defaults to ACTIVE so a fixture that omits it gets an active project; archived
74	            // defaults to FALSE (the table default) unless the fixture pins it.
75	            new Insert("projects")
76	                    .set("id", id(p, "id"))
77	                    .set("name", p.get("name"))
78	                    .set("client_id", id(p, "clientId"))
79	                    .set("status", p.get("status") == null ? "ACTIVE" : p.get("status").toString())
80	                    .setIfPresent("archived", p.get("archived"))
81	                    .setIfPresent("budget", asDouble(p.get("budget")))
82	                    .run();
83	        }
84	    }
85	
86	    private void seedContacts(Map<String, Object> fixture) {
87	        for (Map<String, Object> ct : rows(fixture, "contacts")) {
88	            jdbc.update(
89	                    "INSERT INTO contacts (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
90	                    id(ct, "id"), id(ct, "clientId"), ct.get("name"), ct.get("email"),
91	                    ct.get("role"));
92	        }
93	    }
94	
95	    private void seedInvoices(Map<String, Object> fixture) {
96	        for (Map<String, Object> in : rows(fixture, "invoices")) {
97	            // Insert only the columns the fixture supplies, so the table's own defaults apply when a
98	            // fixture omits them (a plain null would trip the NOT NULL columns). status defaults to
99	            // DRAFT and amount defaults to 0 — an invoice's amount is derived from its line items,
100	            // so fixtures list lineItems rather than a single typed amount.
101	            new Insert("invoices")
102	                    .set("id", id(in, "id"))
103	                    .set("project_id", id(in, "projectId"))
104	                    .set("status", in.get("status") == null ? "DRAFT" : in.get("status").toString())
105	                    .setIfPresent("amount", asDouble(in.get("amount")))
106	                    .setIfPresent("issued_date", asText(in.get("issuedDate")))
107	                    .setIfPresent("due_date", asText(in.get("dueDate")))
108	                    .run();
109	            seedLineItems(in);
110	        }
111	    }
112	
113	    private void seedLineItems(Map<String, Object> invoice) {
114	        long invoiceId = id(invoice, "id");
115	        for (Map<String, Object> li : rows(invoice, "lineItems")) {
116	            jdbc.update(
117	                    "INSERT INTO line_items (id, invoice_id, description, qty, unit_price)"
118	                            + " VALUES (?, ?, ?, ?, ?)",
119	                    id(li, "id"), invoiceId, li.get("description"),
120	                    ((Number) li.get("qty")).intValue(),
121	                    ((Number) li.get("unitPrice")).doubleValue());
122	        }
123	    }
124	
125	    private void seedPayments(Map<String, Object> fixture) {
126	        List<Map<String, Object>> payments = rows(fixture, "payments");
127	        for (Map<String, Object> p : payments) {
128	            jdbc.update(
129	                    "INSERT INTO payments (id, invoice_id, amount, paid_date) VALUES (?, ?, ?, ?)",
130	                    id(p, "id"), id(p, "invoiceId"), asDouble(p.get("amount")),
131	                    asText(p.get("date")));
132	        }
133	        if (!payments.isEmpty()) {
134	            // Seeding explicit ids does not advance H2's identity counter, so bump it past the
135	            // seeded rows or the app's next generated payment id would collide with a fixture id.
136	            Long next = jdbc.queryForObject("SELECT MAX(id) + 1 FROM payments", Long.class);
137	            jdbc.execute("ALTER TABLE payments ALTER COLUMN id RESTART WITH " + next);
138	        }
139	    }
140	
141	    private void seedTasks(Map<String, Object> fixture) {
142	        for (Map<String, Object> t : rows(fixture, "tasks")) {
143	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
144	                    id(t, "id"), id(t, "projectId"), t.get("title"),
145	                    Boolean.TRUE.equals(t.get("done")));
146	        }
147	    }
148	
149	    private void seedTags(Map<String, Object> fixture) {
150	        for (Map<String, Object> tg : rows(fixture, "tags")) {
151	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)", id(tg, "id"), tg.get("name"));
152	        }
153	    }
154	
155	    private void seedNotes(Map<String, Object> fixture) {
156	        List<Map<String, Object>> notes = rows(fixture, "notes");
157	        for (Map<String, Object> n : notes) {
158	            jdbc.update(
159	                    "INSERT INTO notes (id, target_type, target_id, text, created_at)"
160	                            + " VALUES (?, ?, ?, ?, ?)",
161	                    id(n, "id"), n.get("targetType"), id(n, "targetId"), n.get("text"),
162	                    n.get("at").toString());
163	        }
164	        if (!notes.isEmpty()) {
165	            // Seeding explicit ids does not advance H2's identity counter, so bump it past the
166	            // seeded rows or the app's next generated note id would collide with a fixture id.
167	            Long next = jdbc.queryForObject("SELECT MAX(id) + 1 FROM notes", Long.class);
168	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + next);
169	        }
170	    }
171	
172	    private void seedProjectTags(Map<String, Object> fixture) {
173	        for (Map<String, Object> pt : rows(fixture, "projectTags")) {
174	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
175	                    id(pt, "projectId"), id(pt, "tagId"));
176	        }
177	    }
178	
179	    /** The list of fixture rows under {@code key}, or an empty list when the fixture omits it. */
180	    @SuppressWarnings("unchecked")
181	    private static List<Map<String, Object>> rows(Map<String, Object> fixture, String key) {
182	        return (List<Map<String, Object>>) fixture.getOrDefault(key, List.of());
183	    }
184	
185	    /** A fixture id column: JSON numbers arrive as {@link Number}, the tables use {@code BIGINT}. */
186	    private static long id(Map<String, Object> row, String key) {
187	        return ((Number) row.get(key)).longValue();
188	    }
189	
190	    private static Double asDouble(Object value) {
191	        return value == null ? null : ((Number) value).doubleValue();
192	    }
193	
194	    private static String asText(Object value) {
195	        return value == null ? null : value.toString();
196	    }
